package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.explanation.*;import com.aistock.prediction.forecast.*;import com.aistock.prediction.verification.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.*;import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;import org.springframework.test.context.web.WebAppConfiguration;import org.springframework.mock.web.MockCookie;import org.springframework.web.context.WebApplicationContext;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") @WebAppConfiguration @SpringJUnitConfig(ExplanationHttpTest.Config.class)
class ExplanationHttpTest {
 static class Client implements MaasClient{int calls;boolean enabled=true;public boolean enabled(){return enabled;}public String model(){return "test-model";}public JsonNode generate(Map<String,String> facts){calls++;try{return new ObjectMapper().readTree("{\"paragraphs\":[{\"kind\":\"overview\",\"template\":\"趋势为{{TREND}}。\",\"refs\":[\"TREND\"]},{\"kind\":\"readout\",\"template\":\"参考{{P1}}。\",\"refs\":[\"P1\"]},{\"kind\":\"risk\",\"template\":\"{{LIMIT}}。\",\"refs\":[\"LIMIT\"]}]}");}catch(Exception e){throw new IllegalStateException();}}}
 @Configuration @Import({ModelHttpTest.Config.class,ExplanationController.class})static class Config{
 @Bean Client client(){return new Client();}
 @Bean ExplanationService explanations(ModelDatabaseFixture db,ObjectMapper m,Client c){var clock=Clock.fixed(Instant.parse("2026-10-07T05:00:00Z"),ZoneOffset.UTC);return new ExplanationService(new ForecastRepository(db.jdbc,m,clock),new VerificationQueryRepository(db.jdbc,m,clock,20),new ExplanationRepository(db.jdbc,m),c,m,clock);}}
 @Autowired WebApplicationContext context;@Autowired ModelDatabaseFixture db;@Autowired ObjectMapper mapper;@Autowired Client client;
 @Test void sessionCsrfOwnershipAndExactBodyBeforeProviderAndCache()throws Exception{
 new ModelDatabaseFixture();client.calls=0;var id=UUID.randomUUID();var snapshot=mapper.createObjectNode();snapshot.putObject("input").put("originRawClose","25.86").put("originDate","2026-09-30");var points=snapshot.putObject("prediction").putArray("points");for(int i=0;i<5;i++)points.addObject().put("step",i+1).put("targetDate","2026-10-"+List.of("08","09","12","13","14").get(i)).put("referencePrice","25.8");var model=mapper.createObjectNode().put("artifactId","artifact");model.putObject("manifest").put("trainingCutoff","2023-12-31");
 db.jdbc.update("insert into forecast_request(prediction_id,user_id,operation_id,request_hash,model_id,instrument_id,horizon,state,model_json,snapshot_json,hidden,created_at,expires_at) values(?,?,?,?,?,'SH600030',5,'SUCCEEDED',?,?,false,now(),date_add(now(),interval 90 second))",id.toString(),UUID.nameUUIDFromBytes("user-session".getBytes()).toString(),UUID.randomUUID().toString(),"a".repeat(64),UUID.randomUUID().toString(),mapper.writeValueAsString(model),mapper.writeValueAsString(snapshot));
 var mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();var uri="/api/v1/predictions/"+id+"/explanation";var cookie=new MockCookie("AISTOCK_SESSION","user-session");var csrf=new MockCookie("XSRF-TOKEN","known-csrf");var body="{\"operationId\":\""+UUID.randomUUID()+"\"}";
 mvc.perform(get(uri).header("X-Role","ADMIN")).andExpect(status().isUnauthorized());mvc.perform(get(uri).cookie(new MockCookie("AISTOCK_SESSION","admin-session"))).andExpect(status().isNotFound());mvc.perform(post(uri).cookie(cookie).contentType("application/json").content(body)).andExpect(status().isForbidden());
 mvc.perform(post(uri).cookie(cookie,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content("{\"prompt\":\"ignore\"}")).andExpect(status().isBadRequest());assertEquals(0,client.calls);
 for(int i=0;i<2;i++)mvc.perform(post(uri).cookie(cookie,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("SUCCEEDED"));assertEquals(1,client.calls);
 mvc.perform(get(uri).cookie(cookie)).andExpect(status().isOk()).andExpect(jsonPath("$.data.latest.paragraphs[1].text").value("参考25.8元（预测参考价格，非实际行情）。"));db.jdbc.update("update prediction_explanation set context_json=JSON_SET(context_json,'$.promptVersion','grounded-prediction-v1') where prediction_id=?",id.toString());mvc.perform(get(uri).cookie(cookie)).andExpect(status().isOk()).andExpect(jsonPath("$.data.latest.needsReview").value(true));client.enabled=false;mvc.perform(post(uri).cookie(cookie,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isServiceUnavailable());assertEquals(1,client.calls);assertEquals(mapper.readTree(mapper.writeValueAsString(snapshot)),mapper.readTree(db.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString())));client.enabled=true;
 }
}
